import java.util.Map;
import java.util.WeakHashMap;

public class MetadataCache {
    // Use WeakHashMap to bind transient metadata to heavy request objects
    private final Map<RequestContext, RequestMetrics> metricsCache = new WeakHashMap<>();

    public void trackRequest(RequestContext context, RequestMetrics metrics) {
        synchronized (metricsCache) {
            metricsCache.put(context, metrics);
        }
    }

    public RequestMetrics getMetrics(RequestContext context) {
        synchronized (metricsCache) {
            return metricsCache.get(context);
        }
    }
}

class RequestContext {}
class RequestMetrics {}
